# IDNA 2003 name preparation uses the Unicode 3.2 tables.
def _contains(number, ranges):
    for lo, hi in ranges:
        if lo <= number <= hi:
            return True
    return False

def _mapping(number):
    block = _mapped.get(number >> 8, '')
    marker = '\n%02x:' % (number & 255)
    pos = block.find(marker)
    if pos < 0:
        return [number]
    pos += len(marker)
    value = block[pos:block.find('\n', pos)]
    return [int(x, 16) for x in value.split(',')] if value else []

def _composition(one, two):
    block = _compose.get(one >> 8, '')
    marker = '\n%02x,%x:' % (one & 255, two)
    pos = block.find(marker)
    if pos < 0:
        return None
    pos += len(marker)
    return int(block[pos:block.find('\n', pos)], 16)

def nameprep(label):
    numbers = []
    for c in label:
        for n in _mapping(ord(c)):
            cc = _combining.get(n, 0)
            at = len(numbers)
            if cc:
                while at > 0 and _combining.get(numbers[at - 1], 0) > cc:
                    at -= 1
            numbers.insert(at, n)
    result = []
    starter = -1
    last_cc = 0
    for n in numbers:
        cc = _combining.get(n, 0)
        combined = _composition(result[starter], n) if starter >= 0 else None
        if combined is not None and (last_cc == 0 or last_cc < cc):
            result[starter] = combined
        else:
            if cc == 0:
                starter = len(result)
            result.append(n)
            last_cc = cc
    for n in result:
        if _contains(n, _prohibited):
            raise UnicodeError('Invalid character ' + repr(chr(n)))
    has_randal = any(_contains(n, _randal) for n in result)
    if has_randal:
        if any(_contains(n, _left) for n in result):
            raise UnicodeError('Violation of BIDI requirement 2')
        if not _contains(result[0], _randal) or not _contains(result[-1], _randal):
            raise UnicodeError('Violation of BIDI requirement 3')
    return ''.join(chr(n) for n in result)

def _adapt(delta, count, first):
    delta = delta // 700 if first else delta // 2
    delta += delta // count
    k = 0
    while delta > 455:
        delta //= 35
        k += 36
    return k + (36 * delta) // (delta + 38)

_digits = 'abcdefghijklmnopqrstuvwxyz0123456789'

def punycode_encode(text):
    points = [ord(c) for c in text]
    result = ''.join(chr(n) for n in points if n < 128)
    basic = len(result)
    handled = basic
    if basic:
        result += '-'
    n = 128
    delta = 0
    bias = 72
    while handled < len(points):
        m = min(c for c in points if c >= n)
        delta += (m - n) * (handled + 1)
        n = m
        for c in points:
            if c < n:
                delta += 1
            if c == n:
                q = delta
                k = 36
                while True:
                    t = min(26, max(1, k - bias))
                    if q < t:
                        break
                    result += _digits[t + (q - t) % (36 - t)]
                    q = (q - t) // (36 - t)
                    k += 36
                result += _digits[q]
                bias = _adapt(delta, handled + 1, handled == basic)
                delta = 0
                handled += 1
        delta += 1
        n += 1
    return result

def punycode_decode(text):
    split = text.rfind('-')
    result = [ord(c) for c in text[:split]] if split >= 0 else []
    pos = split + 1
    n = 128
    i = 0
    bias = 72
    while pos < len(text):
        old = i
        weight = 1
        k = 36
        while True:
            if pos >= len(text):
                raise UnicodeError('incomplete punycode string')
            digit = _digits.find(text[pos].lower())
            if digit < 0:
                raise UnicodeError('Invalid extended code point')
            pos += 1
            i += digit * weight
            t = min(26, max(1, k - bias))
            if digit < t:
                break
            weight *= 36 - t
            k += 36
        bias = _adapt(i - old, len(result) + 1, old == 0)
        n += i // (len(result) + 1)
        i %= len(result) + 1
        if n > 0x10ffff:
            raise UnicodeError('Invalid character')
        result.insert(i, n)
        i += 1
    return ''.join(chr(n) for n in result)

def to_ascii(label):
    try:
        return label.encode('ascii')
    except UnicodeEncodeError:
        pass
    label = nameprep(label)
    try:
        return label.encode('ascii')
    except UnicodeEncodeError:
        pass
    if label.startswith('xn--'):
        raise UnicodeError('Label starts with ACE prefix')
    return ('xn--' + punycode_encode(label)).encode('ascii')

def to_unicode(label):
    if not label.lower().startswith('xn--'):
        return label
    decoded = punycode_decode(label[4:])
    if to_ascii(decoded).decode('ascii').lower() != label.lower():
        raise UnicodeError('IDNA does not round-trip')
    return decoded

